         '0efd57249fad48d51b2e26987833575750c02d649fc5277e585073425f181a643fcdab71eb5d5d4862e589e4c164c81b'
         'e649091e9456f1461f78d564ecd01b4ff4aeaea41631d8f6b671de7fad031d436651e43fa575750217d1863904a1fd59'
         'c7d691d0067d425d5d99273f715d5d4a8b4d9deeaa1ff0d188ed6cd344414f8f8035d5d4520b60c8e8a0657249d81a28'
         '60927760f1af42700907e2f5aeaea86518170805c4c07639181402babab27c964e6bababa90c80493800e7e55d9aeaea'
         '009c923615d9e5b575750049342466baba8024293df4c8e38413d3127b82b57575021922daa83a03311def55cee79002'
         'baba800818f183ce88691d95d5d4c0824122895829c800fcebaba803ba4209384dff009454339273800f8002baba9001'
         'cabb26baba802413426baba803b15d8aeaea02cec53225aeaea065a450790a3083bababaa286db2e70d47d72151d5d23'
         '3e3bd5a8a2738dc041c89aeaeae7c9fc8e9c5fc47431c56baf24b4a30c07667e7483c427cedd08f0d676aeaea85b9a33'
         'ffd9', 'hex'),
       'image/jpeg',
       810,
       1080,
       'Три Брата на закатном свету, вид с палубы',
       'владелец платформы'
  FROM places p
 WHERE p.id::text = 'e265d0f0-8187-4d7a-b0e4-fe9be5a2d9e0'
   AND p.ark_id IS NOT NULL
 LIMIT 1
ON CONFLICT (ark_id, position) DO UPDATE
   SET image_data = EXCLUDED.image_data,
       mime_type  = EXCLUDED.mime_type,
       width      = EXCLUDED.width,
       height     = EXCLUDED.height,
       caption    = EXCLUDED.caption,
       author     = EXCLUDED.author,
       s3_url     = NULL,
       created_at = NOW()
 WHERE place_gallery_photos.caption = EXCLUDED.caption;

-- ── Исход называется вслух ────────────────────────────────────────────────
DO $$
DECLARE
  v_ark    uuid;
  v_author text;
  v_count  int;
BEGIN
  SELECT ark_id INTO v_ark FROM places
   WHERE id::text = 'e265d0f0-8187-4d7a-b0e4-fe9be5a2d9e0' AND is_visible AND merged_into_id IS NULL;

  IF v_ark IS NULL THEN
    RAISE WARNING '[1155] живой записи «Скалы Три Брата» нет — снимки не легли';
    RETURN;
  END IF;

  SELECT author INTO v_author FROM ai_route_images WHERE route_id = v_ark;
  IF v_author IS DISTINCT FROM 'владелец платформы' THEN
    RAISE WARNING '[1155] герой «Скалы Три Брата» НЕ встал: там %', COALESCE('автор «' || v_author || '»', 'строки снимка нет');
  END IF;

  SELECT COUNT(*) INTO v_count FROM place_gallery_photos
   WHERE ark_id = v_ark AND author = 'владелец платформы' AND position IN (1, 2);
  IF v_count <> 2 THEN
    RAISE WARNING '[1155] галерея «Скалы Три Брата»: легло % из 2 кадров владельца', v_count;
  END IF;
END $$;

COMMIT;
